mapper.select:
select 

from user_info
where user_id = #{userId,jdbcType=BIGINT}

select
from user_info where delete_flag=0
and org_name like CONCAT(CONCAT('%',#{orgName,jdbcType=VARCHAR}), '%')
and nick_name like CONCAT(CONCAT('%',#{nickName,jdbcType=VARCHAR}), '%')
and user_type = #{type,jdbcType=INTEGER}
and org_id = #{orgId,jdbcType=BIGINT}
and user_tel like CONCAT(CONCAT('%',#{userTel,jdbcType=VARCHAR}), '%')
and user_name like CONCAT(CONCAT('%',#{userName,jdbcType=VARCHAR}), '%')
ORDER BY create_time desc limit #{pageIndex} , #{pageSize}

select * from user_info where org_id = #{orgId,jdbcType=BIGINT}

    and user_name  like  CONCAT(CONCAT('%',#{userName,jdbcType=VARCHAR}), '%')


    and nick_name  like  CONCAT(CONCAT('%',#{nickName,jdbcType=VARCHAR}), '%')


    and user_tel  like  CONCAT(CONCAT('%',#{userTel,jdbcType=VARCHAR}), '%')

limit #{pageIndex} , #{pageSize}

SELECT b.user_id,b.user_name,b.nick_name,b.org_id FROM user_info b left JOIN bus_user_role a on b.user_id = a.user_id
where a.role_id =#{bsRoleId,jdbcType=BIGINT}

    and org_id IN

        #{orgId}

select a.* from user_info a left join bus_user_role r on a.user_id = r.user_id left join survey_investigator s on a.user_id = s.user_id where 1 = 1
and s.org_id = #{orgId,jdbcType=BIGINT}
and r.role_id = #{roleId,jdbcType=BIGINT}

select u.* from user_info u
left join bus_user_role b on u.user_id = b.user_id
left join survey_user_consignor c on u.user_id = c.user_id and c.delete_flag = 0
left join survey_user_franchisee f on u.user_id = f.user_id and f.delete_flag = 0
where u.delete_flag = 0 and b.role_id = 53

  and c.consignor_id = #{entrustOrgId,jdbcType=BIGINT}


  and f.franchisee_id = #{surveyOrgId,jdbcType=BIGINT}


    and c.consignor_id in

        #{item.id}


group by u.user_id order by user_id desc

select.if:
select t.id surveyAssorgCaseId,t.survey_info_id surveyInfoId,t.survey_case_no surveyCaseNo,t.survey_no surveyNo, t.entrust_org_name entrustOrgName,t.survey_person surveyPerson,t.org_task_remark surveyItem,(case t.services_id when 13 then '全案' else '单点' end) as orgCaseType, max(t.create_time) as assignDate,max(t.report_date) as commitDate,max(t.org_end_time) as orgEndTime,max(t.review_time) as reviewTime, DATE_ADD(max(t.report_date),INTERVAL 1 DAY) as reviewEndTime, DATE_FORMAT(max(t.create_time),'%Y-%m-%d %H:%i') as assignDateStr,DATE_FORMAT(max(t.report_date),'%Y-%m-%d %H:%i') as commitDateStr,DATE_FORMAT(max(t.org_end_time),'%Y-%m-%d %H:%i') as orgEndTimeStr, t.aging_real agingOrg,(case when t.return_state > 0 then 1 else 0 end) as veto,(case when sum(ifnull(i.assess_sun_score,0)) > 0 then 1 else 0 end) as sun,DATE_FORMAT(max(t.review_time),'%Y-%m-%d %H:%i') as reviewTimeStr, DATE_FORMAT(DATE_ADD(max(t.report_date),INTERVAL 1 DAY),'%Y-%m-%d %H:%i') as reviewEndTimeStr,sum(ifnull(i.assess_score,0)) as totalScore,sum(ifnull(i.assess_sun_score,0)) as sunScore, (sum(ifnull(i.assess_score,0)) - sum(ifnull(i.assess_sun_score,0))) as basScore, t.review_user_id reviewUserId,t.review_user_name reviewUserName,t.orgId,t.survey_info_id from ( select o.id,o.survey_info_id,s.survey_case_no,r.survey_no,s.survey_person,r.entrust_org_name,o.org_task_remark,o.create_time,o.report_date,o.org_end_time,o.return_state,o.review_user_id,o.review_user_name, o.aging_real,o.review_time, (case f.`level` when 1 then f.id else f.parent_id end) as orgId,o.org_survey_state,o.services_id from survey_assign_org o left join survey_franchisee f on o.survey_org_id = f.id left join survey_risk_case_info r on o.survey_info_id = r.id left join survey_risk_case s on r.survey_id = s.id left join survey_consignor n on r.entrust_org_id = n.id where o.delete_flag = 0 and r.delete_flag = 0 -- and o.review_time is not null AND r.entrust_report_end_date IS NOT NULL
and find_in_set(r.entrust_org_id,#{entrustOrgIds,jdbcType=VARCHAR})
and DATE_FORMAT(r.entrust_report_end_date,'%Y-%m-%d') >= DATE_FORMAT(#{startTime,jdbcType=DATE},'%Y-%m-%d')
and DATE_FORMAT(r.entrust_report_end_date,'%Y-%m-%d') <= DATE_FORMAT(#{endTime,jdbcType=DATE},'%Y-%m-%d')
and n.org_attr = 2
) t left join survey_investigator_case i on t.id = i.survey_assorg_case_id group by t.review_user_id,t.orgId,t.survey_info_id HAVING max(t.org_survey_state) = min(t.org_survey_state) and max(t.org_survey_state) = 4 and sum(ifnull(i.score_sun,0)) > 0 and t.review_user_id = #{reviewUserId,jdbcType=BIGINT}

select t.id surveyAssorgCaseId,t.survey_info_id surveyInfoId,t.survey_case_no surveyCaseNo,t.survey_no surveyNo,t.entrust_report_end_date entrustReportEndDate, t.entrust_org_name entrustOrgName,t.survey_person surveyPerson,t.org_task_remark surveyItem,(case t.services_id when 13 then '全案' else '单点' end) as orgCaseType, max(t.create_time) as assignDate,max(t.report_date) as commitDate,max(t.org_end_time) as orgEndTime,max(t.review_time) as reviewTime, DATE_ADD(max(t.report_date),INTERVAL 1 DAY) as reviewEndTime, DATE_FORMAT(max(t.create_time),'%Y-%m-%d %H:%i') as assignDateStr,DATE_FORMAT(max(t.report_date),'%Y-%m-%d %H:%i') as commitDateStr,DATE_FORMAT(max(t.org_end_time),'%Y-%m-%d %H:%i') as orgEndTimeStr, t.aging_real agingOrg,(case when t.return_state > 0 then 1 else 0 end) as veto,(case when sum(ifnull(i.assess_sun_score,0)) > 0 then 1 else 0 end) as sun,DATE_FORMAT(max(t.review_time),'%Y-%m-%d %H:%i') as reviewTimeStr, DATE_FORMAT(DATE_ADD(max(t.report_date),INTERVAL 1 DAY),'%Y-%m-%d %H:%i') as reviewEndTimeStr,sum(ifnull(i.assess_score,0)) as totalScore,sum(ifnull(i.assess_sun_score,0)) as sunScore, (sum(ifnull(i.assess_score,0)) - sum(ifnull(i.assess_sun_score,0))) as basScore, t.review_user_id reviewUserId,t.review_user_name reviewUserName,t.orgId,t.survey_info_id from ( select o.id,o.survey_info_id,s.survey_case_no,r.survey_no,s.survey_person,r.entrust_org_name,o.org_task_remark,o.create_time,o.report_date,o.org_end_time,o.return_state,o.review_user_id,o.review_user_name, o.aging_real,o.review_time,r.entrust_report_end_date, (case f.`level` when 1 then f.id else f.parent_id end) as orgId,o.org_survey_state,o.services_id from survey_assign_org o left join survey_franchisee f on o.survey_org_id = f.id left join survey_risk_case_info r on o.survey_info_id = r.id left join survey_risk_case s on r.survey_id = s.id left join survey_consignor n on r.entrust_org_id = n.id where o.delete_flag = 0 and r.delete_flag = 0 and o.review_time is not null and n.org_attr = 2 AND r.entrust_report_end_date IS NOT NULL and DATE_FORMAT(r.entrust_report_end_date,'%Y-%m-%d') >= DATE_FORMAT(#{startTime,jdbcType=DATE},'%Y-%m-%d') and DATE_FORMAT(r.entrust_report_end_date,'%Y-%m-%d') <= DATE_FORMAT(#{endTime,jdbcType=DATE},'%Y-%m-%d')
and find_in_set(r.entrust_org_id,#{entrustOrgIds,jdbcType=VARCHAR})
) t left join survey_investigator_case i on t.id = i.survey_assorg_case_id group by t.id HAVING max(t.org_survey_state) = min(t.org_survey_state) and max(t.org_survey_state) = 4 and t.review_user_id = #{reviewUserId,jdbcType=BIGINT}

mapper.select:
select A.* from
(
    SELECT u.* FROM user_info u
    LEFT JOIN bus_user_role r ON u.user_id = r.user_id
    WHERE 1 = 1 and u.delete_flag = 0
      AND r.role_id = #{needId,jdbcType=BIGINT}
)A
LEFT JOIN bus_user_role r ON A.user_id = r.user_id and r.role_id = #{noNeedId,jdbcType=BIGINT}
where r.id is null;
